parameters.command:
cd /work/output/artifacts/skill-flow-e2e-devcon-expense-approval/ExpenseApproval/ExpenseApproval

# Save registry outputs to temp files
uip maestro flow registry get core.action.script --output json > /tmp/script-def.json
uip maestro flow registry get core.control.end --output json > /tmp/end-def.json
uip maestro flow registry get uipath.human-in-the-loop.quick-form --output json > /tmp/hitl-def.json

# Write the build plan
cat > /tmp/expense-plan.json << 'PLAN'
{
  "ops": [
    {
      "op": "add-node",
      "id": "fetchExpense",
      "type": "core.action.script",
      "definitionFile": "/tmp/script-def.json",
      "label": "Fetch Expense Details",
      "inputs": {
        "script": "return { expenseId: 'EXP-001', amount: 1500.00, submitterName: 'Jane Doe', category: 'Travel' };"
      }
    },
    {
      "op": "add-node",
      "id": "managerReview",
      "type": "uipath.human-in-the-loop.quick-form",
      "definitionFile": "/tmp/hitl-def.json",
      "label": "Manager Review",
      "inputs": {
        "title": "Expense Approval Request",
        "priority": "Medium",
        "schema": {
          "schemaId": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
          "fields": [
            { "id": "expenseId",       "label": "Expense ID",    "type": "text",   "direction": "input",  "binding": "vars.fetchExpense.output.expenseId" },
            { "id": "amount",          "label": "Amount ($)",    "type": "number", "direction": "input",  "binding": "vars.fetchExpense.output.amount" },
            { "id": "submitterName",   "label": "Submitted By",  "type": "text",   "direction": "input",  "binding": "vars.fetchExpense.output.submitterName" },
            { "id": "category",        "label": "Category",      "type": "text",   "direction": "input",  "binding": "vars.fetchExpense.output.category" },
            { "id": "rejectionReason", "label": "Rejection Reason", "type": "text", "direction": "output", "variable": "vars.rejectionReason" }
          ],
          "outcomes": [
            { "id": "approve", "name": "Approve", "type": "string", "isPrimary": true,  "action": "Continue" },
            { "id": "reject",  "name": "Reject",  "type": "string", "isPrimary": false, "action": "Continue" }
          ]
        },
        "recipient": {
          "channels": ["Email", "ActionCenter"],
          "connections": {},
          "assignee": {
            "type": "group",
            "group": "expense-approvers"
          }
        }
      }
    },
    {
      "op": "add-node",
      "id": "logOutcome",
      "type": "core.action.script",
      "definitionFile": "/tmp/script-def.json",
      "label": "Log Approval Outcome",
      "inputs": {
        "script": "const decision = $vars.managerReview.status;\nconst expenseId = $vars.fetchExpense.output.expenseId;\nconst approved = decision === 'Approve';\nconst reason = $vars.managerReview.output.rejectionReason;\nreturn {\n  expenseId: expenseId,\n  decision: decision,\n  approved: approved,\n  rejectionReason: approved ? null : (reason || 'No reason provided'),\n  logMessage: approved\n    ? 'Expense ' + expenseId + ' approved by manager'\n    : 'Expense ' + expenseId + ' rejected: ' + (reason || 'No reason provided')\n};"
      }
    },
    {
      "op": "add-node",
      "id": "endApproval",
      "type": "core.control.end",
      "definitionFile": "/tmp/end-def.json",
      "label": "End",
      "outputs": "none"
    },
    { "op": "add-edge", "source": "start",         "sourcePort": "output",    "target": "fetchExpense",  "targetPort": "input" },
    { "op": "add-edge", "source": "fetchExpense",   "sourcePort": "success",   "target": "managerReview", "targetPort": "input" },
    { "op": "add-edge", "source": "managerReview",  "sourcePort": "completed", "target": "logOutcome",    "targetPort": "input" },
    { "op": "add-edge", "source": "logOutcome",     "sourcePort": "success",   "target": "endApproval",   "targetPort": "input" }
  ]
}
PLAN

# Apply the plan
python3 /home/azureuser/projects/skills/tmp/skills/uipath-maestro-flow/scripts/flow_edit.py \
  apply --flow ExpenseApproval.flow --plan /tmp/expense-plan.json

echo "--- plan applied ---"
